import { weatherU, weatherFx } from '../../core/shared';
import { water } from '../../core/water';
import { hrInside } from '../../bridges/han-tunnel/profile';
import { bridgeImpacts, windAt, beaufort } from './impact';
import { applyAtmosphere, buildAtmosphere } from './atmosphere';
import { buildRain, updateRain, type Rain } from './rain';
import { applyWetness, buildWetness, wetMaterials } from './wetness';
import { buildWind, updateWind, swayNow } from './wind';
import { buildLightning, updateLightning, type Lightning } from './lightning';
import { attachSwing, updateHooks } from './effectsHooks';
import { buildSummer, updateSummer } from './summer';
import { buildFallen, fellTrees, standTrees, updateFallen, fallenState, fallenSnapshot } from './fallen';
import { createScenario, type Scenario } from './scenario';
import { updateWeatherSound } from './sound';
import { controls } from '../../core/renderer';
import { createWeatherState, setPreset, stepWeather, windNow, type PresetName, type WeatherParams, type WeatherState } from './state';

/* ===== [weather] Thời tiết — Giai đoạn 7: khí quyển + mưa + mặt ướt + gió + bão (chớp, đóng cầu, khoá quay, dừng trình diễn) + kịch bản bão + nắng hè (ảo ảnh, võng cáp) + cây đổ sau bão + âm thanh =====
   Giữ trạng thái (current/target/wet), nhận preset, ghi weatherU, điều biến khí quyển (atmosphere.ts), mưa (rain.ts, +1 draw call khi mưa),
   mặt ướt (wetness.ts + option `weather` của bridgePatch), gió (wind.ts + option `sway` của bridgePatch, 0 draw call),
   chớp (lightning.ts, +1 draw call lúc nháy), vận hành (effectsHooks.ts: weatherFx cho xe, thuyền, trình diễn, cầu quay, quảng cáo). Preset `now` là no-op, 0 draw call mới.
   Gọi buildWeather() SAU buildRiverfront() (sau mọi rand()); updateWeather() ngay sau applyNight() trong animate(). */
export interface Weather {
  state: WeatherState; enabled: boolean; rain: Rain; lightning: Lightning;
  scenario: Scenario;                                                  // kịch bản bão (UI gắn on.caption; camera chế độ 'storm' đọc pose())
  fallen: { state: typeof fallenState; fell: () => void; stand: () => void; snapshot: typeof fallenSnapshot };   // cây đổ sau bão (API test): fell() đổ ngay quanh điểm nhìn, stand() dựng lại, snapshot() = ma trận thân/tán
  attachSwing: typeof attachSwing;                                     // gán predicate khoá quay cho SwingController (main.ts)
  fx: () => typeof weatherFx;                                          // hệ số vận hành đang áp (xe, thuyền, trình diễn, cầu quay) — cho test
  setPreset: (name: PresetName) => void; setIntensity: (k: number) => void;
  setRainCount: (n: number) => void; wetMaterials: () => THREE.MeshStandardMaterial[];
  impact: () => ReturnType<typeof bridgeImpacts>;
  windAt: (z: number) => number; beaufort: (v?: number) => number;
  setParams: (p: Partial<WeatherParams>, instant?: boolean) => void;   // ghi đè target (test / kịch bản); instant: gán luôn current
  sway: () => ReturnType<typeof swayNow>;                              // biên độ lắc đang hiển thị (m, đã phóng đại)
}
let current: Weather | null = null;
export const getWeather = () => current;

export function buildWeather(): Weather {
  const state = createWeatherState();
  buildAtmosphere();                       // chụp giá trị gốc (sương, Sky, nước, mây) trước khi áp thời tiết
  buildWetness();                          // đăng ký đường chung; đường các cầu đã registerWet() trong materials.ts của cầu
  const rain = buildRain();                // mesh mưa ẩn, program biên dịch sẵn
  buildSummer();                           // vá shader đường (ảo ảnh); võng cáp qua option `sag` của bridgePatch
  buildFallen();                           // quét cặp thân–tán cây (sau mọi lệnh dựng và dọn cây)
  buildWind();                            // vá shader tán cây; dây đã có option `sway` trong materials.ts của cầu
  const lightning = buildLightning();      // mesh tia chớp ẩn, program biên dịch sẵn
  current = {
    state, enabled: CONFIG.weather.enabled, rain, lightning, attachSwing, fx: () => weatherFx,
    scenario: createScenario(state, (on) => { current.enabled = on; }, standTrees),
    fallen: { state: fallenState, fell: () => fellTrees(controls.target, state.current.windDir), stand: standTrees, snapshot: fallenSnapshot },
    setPreset(name) { setWeatherPreset(name); },
    setIntensity(k) { setWeatherIntensity(k); },
    setRainCount: (n: number) => rain.setCount(n),
    wetMaterials,
    impact: () => bridgeImpacts(state.current),
    windAt: (z: number) => windAt(z, state.current.wind),
    beaufort: (v?: number) => beaufort(v ?? state.current.wind),
    setParams(p, instant = false) { Object.assign(state.target, p); if (instant) Object.assign(state.current, p); current.enabled = true; },
    sway: swayNow
  };
  return current;
}

export function setWeatherPreset(name: PresetName) {
  if (!current) return;
  current.scenario.stop(false);            // người xem tự chọn: kịch bản dừng, không trả preset cũ
  if (name !== 'now') standTrees();         // rời trạng thái "sau bão"
  setPreset(current.state, name);
  current.enabled = name !== 'now';
}
export function setWeatherIntensity(k: number) {
  if (!current) return;
  current.scenario.stop(false);
  setPreset(current.state, current.state.preset, k);
}

export function updateWeather(dt: number, time: number, night: number, cam: THREE.Camera) {
  if (!current) return;
  const s = current.state;
  current.scenario.update(dt);
  stepWeather(s, dt);
  applyAtmosphere(s, night, dt);
  const c = s.current, w = windNow(c, time), wet = s.wet < 1e-3 ? 0 : s.wet;   // dưới ngưỡng: 0 chính xác để nhánh shader ướt không chạy
  applyWetness(wet);
  updateWind(c, w, current.enabled);       // lắc dây/cây, thuyền, lửa, sóng (0 draw call)
  const p = cam.position, blocked = hrInside(p.x, p.y, p.z) || p.y < water.position.y;   // camera trong hầm / dưới mặt nước
  updateRain(dt, c.rain < 1e-3 ? 0 : c.rain, w, c.windDir, blocked);   // tắt mưa trong hầm / dưới mặt nước
  updateLightning(dt, c.lightning, blocked);                          // sau applyAtmosphere: cộng xung hemi / exposure
  updateSummer(c, current.enabled);                                   // võng cáp phóng đại khi nóng
  aftermath(s, dt);                                                   // bão qua đỉnh rồi lặng: cây đổ
  updateFallen(dt);
  updateWeatherSound(dt, c, w, blocked, current.lightning);           // mưa, gió, sấm (Web Audio, chỉ khi người xem bật âm thanh)
  updateHooks(c, dt);                                                // đóng cầu, khoá quay, dừng trình diễn, thuyền về bến, quảng cáo
  weatherU.uWet.value = wet; weatherU.uRain.value = c.rain; weatherU.uWind.value = c.wind; weatherU.uGust.value = Math.max(0, w - c.wind);
  weatherU.uHaze.value = c.haze; weatherU.uSwayK.value = current.enabled ? CONFIG.weather.swayExaggeration : 0;
}

/* Sau bão (mục 4.8): gió hiện tại từng đạt armWind rồi gió đích xuống dưới calmWind (và hết cấm) → cây đổ quanh điểm nhìn.
   Đang chạy kịch bản: đổ quanh điểm nhìn của mốc đang chạy (camera lúc đó còn đang bay tới). Rời trạng thái: hết `hold` giây, gió đích lại tăng, chọn preset khác 'now', hoặc kịch bản kết thúc/dừng. Chưa từng có bão thì không đụng cây. */
let armed = false, afterT = -1;
function aftermath(s: WeatherState, dt: number) {
  const F = CONFIG.weather.fallen, sc = current.scenario;
  if (s.current.wind >= F.armWind) armed = true;
  if (armed && s.target.wind <= F.calmWind && !s.target.closed) { armed = false; fellTrees(sc.running ? sc.focus() : controls.target, s.current.windDir); afterT = 0; }
  if (afterT >= 0) {
    afterT += dt;
    if (afterT > F.hold || s.target.wind > F.calmWind) { standTrees(); afterT = -1; }
  }
}
import { CONFIG } from '../../config';
import { rng } from '../../common/math';

/* ===== [weather] Trạng thái thời tiết: tham số liên tục, preset, tiến dần về target, nhiễu gió =====
   Module THUẦN: không import three/scene. Ngẫu nhiên dùng rng(CONFIG.weather.seed + k), KHÔNG dùng rand(). */
export interface WeatherParams {
  temp: number;      // °C — nhiệt độ không khí
  rain: number;      // 0 → 1 — cường độ mưa
  wind: number;      // m/s ở 10 m — gió trung bình
  gust: number;      // m/s — biên độ gió giật cộng thêm
  windDir: number;   // rad — hướng gió THỔI TỚI (0 = sang +X)
  cloud: number;     // 0 → 1 — độ phủ mây
  haze: number;      // 0 → 1 — mù nóng
  level: number;     // m — mực nước sông dâng thêm
  lightning: number; // 0 → 1 — tần suất chớp
  closed: boolean;   // cấm lưu thông qua cầu (theo trạng thái preset / kịch bản, không theo ngưỡng gió)
}
export type PresetName = 'now' | 'summer' | 'rain' | 'monsoon' | 'storm';
export const PRESET_NAMES: PresetName[] = ['now', 'summer', 'rain', 'monsoon', 'storm'];

export interface WeatherState {
  current: WeatherParams; target: WeatherParams;
  wet: number;            // 0 → 1 — mặt ướt (dẫn xuất: lên nhanh theo mưa, khô chậm)
  preset: PresetName; intensity: number;   // 0 → 1 — thanh cường độ nhân lên rain/wind/gust/level
}

/* Giá trị trung tính (không mưa, không gió): đích của preset `now`. */
export const neutralParams = (): WeatherParams => ({ temp: CONFIG.weather.thermal.refTemp, rain: 0, wind: 0, gust: 0, windDir: CONFIG.weather.windDir, cloud: 0, haze: 0, level: 0, lightning: 0, closed: false });

export const createWeatherState = (): WeatherState => ({ current: neutralParams(), target: neutralParams(), wet: 0, preset: 'now', intensity: 1 });

/* Đích của một preset sau khi nhân thanh cường độ k (0–1). `now` -> trung tính. */
export function presetTarget(name: PresetName, k = 1): WeatherParams {
  const p = CONFIG.weather.presets[name], n = neutralParams();
  if (!p) return n;
  const kk = Math.max(0, Math.min(1, k));
  return { ...n, ...p, rain: p.rain * kk, wind: p.wind * kk, gust: p.gust * kk, level: p.level * kk };
}

export function setPreset(s: WeatherState, name: PresetName, k = s.intensity) {
  s.preset = name; s.intensity = Math.max(0, Math.min(1, k));
  s.target = presetTarget(name, s.intensity);
}

const approach = (a: number, b: number, tau: number, dt: number) => b + (a - b) * Math.exp(-dt / Math.max(1e-3, tau));

/* Tiến current về target theo hằng số thời gian riêng từng tham số (giống stepNight). */
export function stepWeather(s: WeatherState, dt: number) {
  const T = CONFIG.weather.tau, c = s.current, t = s.target;
  c.temp = approach(c.temp, t.temp, T.temp, dt);
  c.rain = approach(c.rain, t.rain, T.rain, dt);
  c.wind = approach(c.wind, t.wind, T.wind, dt);
  c.gust = approach(c.gust, t.gust, T.wind, dt);
  c.windDir = t.windDir;
  c.cloud = approach(c.cloud, t.cloud, T.cloud, dt);
  c.haze = approach(c.haze, t.haze, T.haze, dt);
  c.level = approach(c.level, t.level, T.level, dt);
  c.lightning = approach(c.lightning, t.lightning, T.lightning, dt);
  c.closed = t.closed;
  s.wet = approach(s.wet, c.rain, c.rain > s.wet ? T.rain : T.wet, dt);   // ướt nhanh, khô chậm
}

/* Nhiễu gió giật g(t) ∈ [0, 1]: tổng vài tầng nội suy cosin trên bảng ngẫu nhiên có seed (lặp tuần hoàn, không dùng rand()). */
let gustTable: number[][] | null = null;
function gustTables() {
  if (gustTable) return gustTable;
  const G = CONFIG.weather.gust, rnd = rng(CONFIG.weather.seed + 1);
  gustTable = Array.from({ length: G.octaves }, () => Array.from({ length: G.steps }, () => rnd()));
  return gustTable;
}
export function gustNoise(t: number): number {
  const G = CONFIG.weather.gust, tabs = gustTables();
  let sum = 0, amp = 1, norm = 0;
  for (let o = 0; o < G.octaves; o++) {
    const x = Math.abs(t) / (G.period / (1 << o)), i = Math.floor(x), f = x - i, a = tabs[o][i % G.steps], b = tabs[o][(i + 1) % G.steps], u = (1 - Math.cos(f * Math.PI)) / 2;
    sum += (a + (b - a) * u) * amp; norm += amp; amp *= 0.5;
  }
  return sum / norm;
}
/* Gió tức thời ở 10 m: trung bình + giật. */
export const windNow = (c: WeatherParams, t: number) => c.wind + c.gust * gustNoise(t);
import { CONFIG } from '../../config';
import type { WeatherParams } from './state';

/* ===== [weather] Ảnh hưởng của thời tiết lên cầu: gió theo cao độ, cấp Beaufort, giãn nở, võng cáp =====
   Module THUẦN: số lấy từ CONFIG, không ghi cứng. Kết quả là "tính gần đúng" (xem prompts/ke-hoach-thoi-tiet.md mục 1.6). */
export type BridgeKey = 'dragon' | 'thuanPhuoc' | 'tranThiLy' | 'songHan' | 'hanTunnel';
export type BridgeStatus = 'open' | 'limited' | 'closed';
export interface BridgeImpact {
  key: BridgeKey; windDeck: number; windTop: number;   // m/s tại mặt cầu và đỉnh tháp (0 nếu không có tháp)
  level: number;                                       // cấp Beaufort ở mặt cầu
  status: BridgeStatus; effects: string[];             // trạng thái theo thông báo của thành phố; khoá hiệu ứng
  expand: number;                                      // m — giãn nở nhiệt toàn cầu so với nhiệt độ chuẩn
  sag: number;                                         // m — cáp chủ võng thêm (chỉ Thuận Phước)
}

/* Vận tốc gió ở cao độ z (m) từ v10: v(z) = v10 · (z / 10)^α. */
export const windAt = (z: number, v10: number) => v10 * Math.pow(Math.max(z, 1) / CONFIG.weather.windRefH, CONFIG.weather.windAlpha);

/* Cấp Beaufort 0–16 (đếm ngưỡng dưới đã vượt). */
export const beaufort = (v: number) => CONFIG.weather.beaufort.filter(b => v >= b).length;

/* Giãn nở dọc: ΔL = L · α · ΔT. */
export const expansion = (length: number, coef: number, temp: number) => length * coef * (temp - CONFIG.weather.thermal.refTemp);

/* Cáp chủ võng thêm khi nóng, gần đúng parabol: S ≈ L(1 + 8/3 (f/L)²), Δf ≈ 3·L·ΔS / (16·f). */
export function cableSag(temp: number) {
  const { span: L, sagRatio } = CONFIG.weather.cableSag, f = L / sagRatio, S = L * (1 + 8 / 3 * Math.pow(f / L, 2));
  const dS = S * CONFIG.weather.thermal.steel * (temp - CONFIG.weather.thermal.refTemp);
  return 3 * L * dS / (16 * f);
}

/* Cao độ mặt cầu / đỉnh tháp lấy từ CONFIG của từng cầu. */
function heights(): { key: BridgeKey; deck: number; top: number; length: number; coef: number }[] {
  const TP = CONFIG.thuanPhuoc, TTL = CONFIG.tranThiLy, SH = CONFIG.songHan, W = CONFIG.weather.thermal;
  return [
    { key: 'dragon', deck: CONFIG.deckMidY, top: 0, length: CONFIG.length, coef: W.steel },
    { key: 'thuanPhuoc', deck: TP.roadCenterY, top: TP.towerTop, length: TP.totalLength, coef: W.steel },
    { key: 'tranThiLy', deck: Math.max(...TTL.roadProfile.map(p => p[1])), top: TTL.pylonHeight, length: TTL.totalLength, coef: W.concrete },
    { key: 'songHan', deck: SH.deckY, top: 0, length: SH.totalLength, coef: W.steel },
    { key: 'hanTunnel', deck: 0, top: 0, length: 0, coef: 0 }   // hầm ngầm: không chịu gió, không giãn nở theo khí hậu
  ];
}

/* Bảng ảnh hưởng cho từng công trình theo thời tiết hiện tại. */
export function bridgeImpacts(w: WeatherParams): BridgeImpact[] {
  return heights().map(h => {
    const windDeck = windAt(h.deck, w.wind), windTop = h.top ? windAt(h.top, w.wind) : 0, effects: string[] = [];
    if (h.key === 'hanTunnel') return { key: h.key, windDeck: 0, windTop: 0, level: 0, status: 'open' as BridgeStatus, effects, expand: 0, sag: 0 };
    const expand = expansion(h.length, h.coef, w.temp), sag = h.key === 'thuanPhuoc' ? cableSag(w.temp) : 0;
    if (w.rain > 0 && w.wind > 0 && (h.key === 'thuanPhuoc' || h.key === 'tranThiLy' || h.key === 'songHan')) effects.push('rainWindCable');
    if (w.temp - CONFIG.weather.thermal.refTemp >= 8) effects.push('thermal');
    if (w.closed) effects.push(h.key === 'songHan' ? 'swingLocked' : 'closed');
    return { key: h.key, windDeck, windTop, level: beaufort(windDeck), status: (w.closed ? 'closed' : 'open') as BridgeStatus, effects, expand, sag };
  });
}
import { CONFIG } from '../../config';
import { weatherFx } from '../../core/shared';
import { setAdsSuppressed } from '../riverfront';
import type { SwingController } from '../../bridges/song-han/SwingController';
import type { WeatherParams } from './state';

/* ===== [weather] Vận hành khi bão (mục 5.3): hệ số cho giao thông, thuyền, trình diễn, cầu quay, quảng cáo =====
   Chỉ ghi vào weatherFx (core/shared.ts) và gọi hook; KHÔNG đổi nút người dùng (lifeOn, show.on, nút quảng cáo): hết bão tự trả về lựa chọn cũ.
   Cấm lưu thông và khoá quay cầu theo TRẠNG THÁI `closed` (preset Bão / kịch bản), không theo ngưỡng gió — "theo thông báo của thành phố".
   Mặc định (closed = false, mưa = gió = 0) mọi giá trị trung tính: clear = boatAway = 0, showAllowed = true, swingBlocked = false. */
let swing: SwingController | null = null, adsOff = false;

/* Gán predicate khoá quay cho SwingController (gọi một lần ở main.ts) */
export function attachSwing(ctrl: SwingController) {
  swing = ctrl; ctrl.canStart = () => !weatherFx.swingBlocked;
}

const toward = (v: number, goal: number, step: number) => (v < goal ? Math.min(goal, v + step) : Math.max(goal, v - step));

export function updateHooks(c: WeatherParams, dt: number) {
  const O = CONFIG.weather.ops, closed = c.closed;
  weatherFx.clear = toward(weatherFx.clear, closed ? 1 : 0, dt / O.clearSec);          // xe dọn dần trong clearSec, mở lại thì hiện dần
  weatherFx.boatAway = toward(weatherFx.boatAway, closed ? 1 : 0, dt / O.boatAwaySec);   // thuyền về bến
  weatherFx.showAllowed = !closed && c.rain <= O.showMaxRain && c.wind <= O.showMaxWind;
  weatherFx.swingBlocked = closed;
  weatherFx.wheelStopped = closed;                                                       // Vòng quay Mặt Trời giảm tốc tới dừng (sun-wheel/SunWheel.ts); hết bão quay lại tốc độ đã chọn
  if (closed && swing && swing.state === 'OPEN') swing.requestClose();                // đang mở thì đóng sớm
  if (closed !== adsOff) { adsOff = closed; setAdsSuppressed(closed); }                // quảng cáo tắt tạm, hết bão trả lại lựa chọn người dùng
}

